ee:variables.ee:set-variable:
%dw 2.0
output application/java
---
[
  {
    "type": "function",
    name: "get-order-status",
    description: "Retorna status, itens e pagamento de um pedido TechWave",
    parameters: {
      "type": "object",
      properties: { orderId: { "type": "string", description: "Id do pedido, ex.: TW-1001" } },
      required: ["orderId"]
    }
  },
  {
    "type": "function",
    name: "create-support-case",
    description: "Abre um Case de suporte no Salesforce",
    parameters: {
      "type": "object",
      properties: {
        orderId: { "type": "string" },
        subject: { "type": "string" },
        description: { "type": "string" },
        priority: { "type": "string", "enum": ["Low", "Medium", "High"] }
      },
      required: ["orderId", "subject", "description", "priority"]
    }
  },
  {
    "type": "function",
    name: "refund-payment",
    description: "Cria reembolso total no Stripe para um PaymentIntent",
    parameters: {
      "type": "object",
      properties: {
        paymentIntentId: { "type": "string" },
        reason: { "type": "string", "enum": ["duplicate", "fraudulent", "requested_by_customer"] }
      },
      required: ["paymentIntentId", "reason"]
    }
  },
  {
    "type": "function",
    name: "notify-team",
    description: "Envia notificacao ao canal de suporte no Slack",
    parameters: {
      "type": "object",
      properties: { message: { "type": "string" } },
      required: ["message"]
    }
  }
]

ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{
  model: p('config.openai.model'),
  'input': [
    { role: "system", content: vars.systemPrompt },
    { role: "user", content: vars.userPrompt }
  ],
  tools: vars.toolDefs
}

logger.message:
#[output application/json --- {message: 'OpenAI responded (tool selection)', tracePoint: 'AFTER_REQUEST'} ++ ({
        toolCalls: sizeOf((payload.'output' default []) filter ($.'type' == 'function_call'))
      })]

#[output application/json --- {message: 'Tool-calling ceiling reached with pending tool calls', tracePoint: 'EXCEPTION'} ++ ({
            taskId: vars.taskId default 'unknown',
            rounds: vars.toolIteration default 0,
            pendingTools: (vars.toolCalls default []) map ($.name)
          })]

#[output application/json --- {message: 'Tool-calling loop finished', tracePoint: 'END'} ++ ({
            taskId: vars.taskId default 'unknown',
            rounds: vars.toolIteration default 0
          })]

a2a:update-task-artifact.a2a:artifact-content:
#[%dw 2.0
output application/json
---
{
  artifactUpdate: {
    taskId: vars.taskId,
    contextId: vars.contextId,
    artifact: {
      artifactId: "artifact-" ++ vars.taskId,
      name: "answer",
      parts: [{ text: vars.finalAnswer }]
    }
  }
}]

a2a:update-task-status.a2a:status-content:
#[%dw 2.0
output application/json
---
{
  statusUpdate: {
    taskId: vars.taskId,
    contextId: vars.contextId,
    status: {
      state: "TASK_STATE_COMPLETED",
      message: {
        messageId: uuid(),
        role: "ROLE_AGENT",
        parts: [{ text: vars.finalAnswer }]
      }
    }
  }
}]

logger.message:
#[output application/json --- {message: 'Agent task failed: ' ++ error.description, tracePoint: 'EXCEPTION'} ++ ({
            taskId: vars.taskId default 'unknown',
            errorType: error.errorType.identifier default 'UNKNOWN',
            errorDescription: error.description
          })]

a2a:update-task-status.a2a:status-content:
#[%dw 2.0
output application/json
---
{
  statusUpdate: {
    taskId: vars.taskId default uuid(),
    contextId: vars.contextId default ("context-" ++ uuid()),
    status: {
      state: "TASK_STATE_FAILED",
      message: {
        messageId: uuid(),
        role: "ROLE_AGENT",
        parts: [{ text: "Desculpe, ocorreu um erro ao processar sua solicitacao: " ++ (error.description default "erro inesperado") }]
      }
    }
  }
}]

logger.message:
#[output application/json --- {message: 'Tool-calling round', tracePoint: 'START'} ++ ({
        taskId: vars.taskId default 'unknown',
        round: vars.toolIteration,
        tools: (vars.toolCalls default []) map ($.name)
      })]

#[output application/json --- {message: 'Calling MCP tool: ' ++ vars.currentCall.name, tracePoint: 'BEFORE_REQUEST'} ++ ({
          round: vars.toolIteration,
          arguments: vars.currentCall.arguments default '{}'
        })]

#[output application/json --- {message: 'MCP tool responded: ' ++ vars.currentCall.name, tracePoint: 'AFTER_REQUEST'} ++ ({
          round: vars.toolIteration,
          resultPreview: vars.toolOutput
        })]

#[output application/json --- {message: 'OpenAI responded (tool results)', tracePoint: 'AFTER_REQUEST'} ++ ({
        round: vars.toolIteration,
        toolCalls: sizeOf((payload.'output' default []) filter ($.'type' == 'function_call'))
      })]
